// Get the entire binary object from the upstream node
const binaryObject = $('file download supabase.').first().binary;

if (!binaryObject) {
  throw new Error('No binary data found from file download supabase.');
}

// Get the key of the first (and likely only) binary file
const binaryKey = Object.keys(binaryObject)[0];

if (!binaryKey) {
  throw new Error('Binary object is empty.');
}

// Retrieve the actual binary data object using the identified key
const actualBinaryFile = binaryObject[binaryKey];

// We will rename the output key to 'fileToUpload' to avoid confusion.
// Note: If you do this, you must change the 'inputDataFieldName' in the HTTP Request node to 'fileToUpload'.
return {
  json: {},
  binary: {
    fileToUpload: actualBinaryFile
  }
};

